import type { ComponentProps, ReactNode } from 'react';
import { visibleGroups } from '@/components/company-os/nav';
import type { NavGroup } from '@/components/company-os/nav';
import { NavFavorites, NavMain } from '@/components/company-os/nav-main';
import type { Favorite } from '@/components/company-os/nav-main';
import { useActiveNavHref } from '@/components/company-os/use-active-nav-href';
import {
    Sidebar,
    SidebarContent,
    SidebarFooter,
    SidebarHeader,
    SidebarMenu,
    SidebarMenuButton,
    SidebarMenuItem,
} from '@/components/ui/sidebar';
import { Link, toUrl } from '@/lib/navigation';
import type { Href } from '@/lib/navigation';

export function AppSidebar({
    logo,
    homeHref,
    groups,
    permissions,
    favorites = [],
    create,
    footer,
    collapsible = 'icon',
    variant = 'inset',
}: {
    logo: ReactNode;
    homeHref: Href;
    groups: NavGroup[];
    permissions: string[];
    favorites?: Favorite[];
    create?: ReactNode;
    footer?: ReactNode;
    collapsible?: ComponentProps<typeof Sidebar>['collapsible'];
    variant?: ComponentProps<typeof Sidebar>['variant'];
}) {
    const visible = visibleGroups(groups, permissions);
    const activeHref = useActiveNavHref([
        ...favorites.map((favorite) => toUrl(favorite.href)),
        ...visible.flatMap((group) => group.items.map((item) => toUrl(item.href))),
    ]);

    return (
        <Sidebar collapsible={collapsible} variant={variant} data-tour="sidebar">
            <SidebarHeader>
                <SidebarMenu>
                    <SidebarMenuItem>
                        <SidebarMenuButton size="lg" asChild>
                            <Link href={homeHref} prefetch>
                                {logo}
                            </Link>
                        </SidebarMenuButton>
                    </SidebarMenuItem>
                </SidebarMenu>
                {create}
            </SidebarHeader>

            <SidebarContent>
                <NavFavorites favorites={favorites} activeHref={activeHref} />
                {visible.map((group, index) => (
                    <NavMain
                        key={group.label ?? index}
                        label={group.label}
                        items={group.items}
                        activeHref={activeHref}
                    />
                ))}
            </SidebarContent>

            {footer && <SidebarFooter>{footer}</SidebarFooter>}
        </Sidebar>
    );
}

export function AppLogo({ icon, name }: { icon: ReactNode; name: string }) {
    return (
        <>
            <div className="flex aspect-square size-8 items-center justify-center text-primary">
                {icon}
            </div>
            <div className="ml-1 grid flex-1 text-left text-sm">
                <span className="mb-0.5 truncate leading-tight font-bold text-slate-800">
                    {name}
                </span>
            </div>
        </>
    );
}

import { BookmarkIcon } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import type { NavItem } from '@/components/company-os/nav';
import {
    SidebarGroup,
    SidebarGroupLabel,
    SidebarMenu,
    SidebarMenuButton,
    SidebarMenuItem,
} from '@/components/ui/sidebar';
import { Link, toUrl } from '@/lib/navigation';
import type { Href } from '@/lib/navigation';

export type Favorite = {
    id: string;
    title: string;
    href: Href;
    icon?: LucideIcon;
};

export function NavMain({
    label,
    items,
    activeHref,
}: {
    label?: string;
    items: NavItem[];
    activeHref: string | null;
}) {
    return (
        <SidebarGroup className="px-2 py-0">
            {label && <SidebarGroupLabel>{label}</SidebarGroupLabel>}
            <SidebarMenu>
                {items.map((item) => (
                    <SidebarMenuItem key={item.title} data-tour={item.tour}>
                        <SidebarMenuButton
                            asChild
                            isActive={toUrl(item.href) === activeHref}
                            tooltip={{ children: item.title }}
                        >
                            <Link href={item.href} prefetch>
                                {item.icon && <item.icon />}
                                <span>{item.title}</span>
                            </Link>
                        </SidebarMenuButton>
                    </SidebarMenuItem>
                ))}
            </SidebarMenu>
        </SidebarGroup>
    );
}

export function NavFavorites({
    favorites,
    activeHref,
    label = 'Favorites',
}: {
    favorites: Favorite[];
    activeHref: string | null;
    label?: string;
}) {
    if (favorites.length === 0) {
        return null;
    }

    return (
        <NavMain
            label={label}
            activeHref={activeHref}
            items={favorites.map((favorite) => ({
                title: favorite.title,
                href: favorite.href,
                icon: favorite.icon ?? BookmarkIcon,
            }))}
        />
    );
}

import { ChevronsUpDown } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { UserInfo } from '@/components/company-os/user-info';
import type { UserSummary } from '@/components/company-os/user-info';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuGroup,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
    SidebarMenu,
    SidebarMenuButton,
    SidebarMenuItem,
    useSidebar,
} from '@/components/ui/sidebar';
import { useIsMobile } from '@/hooks/use-mobile';
import { Link } from '@/lib/navigation';
import type { Href } from '@/lib/navigation';

export type UserMenuItem = {
    label: string;
    icon?: LucideIcon;
    href?: Href;
    onSelect?: () => void;
};

function MenuEntry({ item }: { item: UserMenuItem }) {
    if (item.href) {
        return (
            <DropdownMenuItem asChild>
                <Link className="block w-full cursor-pointer" href={item.href} onClick={item.onSelect}>
                    {item.icon && <item.icon className="mr-2" />}
                    {item.label}
                </Link>
            </DropdownMenuItem>
        );
    }

    return (
        <DropdownMenuItem onSelect={item.onSelect}>
            {item.icon && <item.icon className="mr-2" />}
            {item.label}
        </DropdownMenuItem>
    );
}

export function NavUser({
    user,
    items,
    logout,
}: {
    user: UserSummary;
    items: UserMenuItem[];
    logout: UserMenuItem;
}) {
    const { state } = useSidebar();
    const isMobile = useIsMobile();

    return (
        <SidebarMenu>
            <SidebarMenuItem>
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <SidebarMenuButton
                            size="lg"
                            className="group text-sidebar-accent-foreground data-[state=open]:bg-sidebar-accent"
                        >
                            <UserInfo user={user} />
                            <ChevronsUpDown className="ml-auto size-4" />
                        </SidebarMenuButton>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent
                        className="w-(--radix-dropdown-menu-trigger-width) min-w-56 rounded-lg"
                        align="end"
                        side={isMobile ? 'bottom' : state === 'collapsed' ? 'left' : 'bottom'}
                    >
                        <DropdownMenuLabel className="p-0 font-normal">
                            <div className="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
                                <UserInfo user={user} showEmail />
                            </div>
                        </DropdownMenuLabel>
                        <DropdownMenuSeparator />
                        <DropdownMenuGroup>
                            {items.map((item) => (
                                <MenuEntry key={item.label} item={item} />
                            ))}
                        </DropdownMenuGroup>
                        <DropdownMenuSeparator />
                        <MenuEntry item={logout} />
                    </DropdownMenuContent>
                </DropdownMenu>
            </SidebarMenuItem>
        </SidebarMenu>
    );
}

import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';

export type UserSummary = {
    name: string;
    email?: string;
    avatar?: string | null;
};

export function initialsOf(name: string): string {
    const parts = name.trim().split(/\s+/u).filter(Boolean);

    if (parts.length === 0) {
        return '';
    }

    const first = Array.from(parts[0])[0] ?? '';
    const last = parts.length > 1 ? (Array.from(parts[parts.length - 1])[0] ?? '') : '';

    return `${first}${last}`.toUpperCase();
}

export function UserInfo({
    user,
    showEmail = false,
}: {
    user: UserSummary;
    showEmail?: boolean;
}) {
    return (
        <>
            <Avatar className="h-8 w-8 overflow-hidden rounded-full">
                {user.avatar && <AvatarImage src={user.avatar} alt={user.name} />}
                <AvatarFallback className="rounded-lg bg-primary/10 text-xs font-semibold text-primary">
                    {initialsOf(user.name)}
                </AvatarFallback>
            </Avatar>
            <div className="grid flex-1 text-left text-sm leading-tight">
                <span className="truncate font-medium">{user.name}</span>
                {showEmail && user.email && (
                    <span className="truncate text-xs text-muted-foreground">
                        {user.email}
                    </span>
                )}
            </div>
        </>
    );
}

import { useSyncExternalStore } from 'react';

const MOBILE_BREAKPOINT = 768;

const mql =
    typeof window === 'undefined'
        ? undefined
        : window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);

function subscribe(callback: (event: MediaQueryListEvent) => void) {
    if (!mql) {
        return () => {};
    }

    mql.addEventListener('change', callback);

    return () => mql.removeEventListener('change', callback);
}

export function useIsMobile(): boolean {
    return useSyncExternalStore(
        subscribe,
        () => mql?.matches ?? false,
        () => false,
    );
}
